<script setup lang="ts">
import { ref,onMounted } from 'vue'
import { ElMessage } from 'element-plus'
import { api,explain,mutationKeys } from '../api/client'
import type { ImportBatch,Group } from '../types'
const file=ref<File|null>(null),source=ref('CAMPUS_CATALOG'),mode=ref('DEMO'),group=ref(''),mapping=ref('{}'),context=ref('{}'),batch=ref<ImportBatch|null>(null),busy=ref(false),error=ref(''),groups=ref<Group[]>([]),keys=mutationKeys()
onMounted(async()=>{try{groups.value=(await api<{items:Group[]}>('/admin/approval-groups')).items}catch(e){error.value=explain(e)}})
function selected(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null;batch.value=null;error.value=''}
async function preview(){busy.value=true;error.value='';batch.value=null;try{if(!file.value)throw new Error('请选择导入文件');if(file.value.size>2*1024*1024)throw new Error('文件不能超过 2 MB');const mappingData=JSON.parse(mapping.value),contextData={...JSON.parse(context.value),...(group.value?{approvalGroupId:group.value}:{})};const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.value.arrayBuffer()))).map(v=>v.toString(16).padStart(2,'0')).join('');const payload={digest,filename:file.value.name,source:source.value,mode:mode.value,mappingData,contextData},data=new FormData();data.set('file',file.value);data.set('importType','RESOURCE_CATALOG');data.set('sourceSystem',source.value);data.set('dataMode',mode.value);data.set('fieldMapping',JSON.stringify(mappingData));data.set('queryContext',JSON.stringify(contextData));batch.value=await api<ImportBatch>('/admin/imports/preview','POST',data,keys.key('preview',payload));keys.done('preview',payload)}catch(e){error.value=explain(e)}finally{busy.value=false}}
async function commit(){if(!batch.value||batch.value.summary.errorRows>0)return;busy.value=true;error.value='';const id=batch.value.batchId;try{batch.value=await api<ImportBatch>('/admin/imports/'+id+'/commit','POST',undefined,keys.key('commit',id));keys.done('commit',id);ElMessage.success('目录导入成功')}catch(e){error.value=explain(e)}finally{busy.value=false}}
</script><template><h1>资料导入</h1><p class="lead">先核对文件、来源与错误，再确认写入资源目录。支持 Excel / JSON，最多 2 MB、2,000 行。</p><el-alert title="这里只导入资源目录；不建立学校占用或空闲覆盖，导入后资源默认草稿。" type="info" :closable="false"/><div class="card"><el-form label-position="top" @submit.prevent="preview"><div class="twocol"><el-form-item label="来源系统"><el-input v-model="source" maxlength="32"/></el-form-item><el-form-item label="数据模式"><el-select v-model="mode"><el-option label="演示资料 DEMO" value="DEMO"/><el-option label="真实来源 REAL" value="REAL"/></el-select></el-form-item><el-form-item label="审批组"><el-select v-model="group" clearable><el-option v-for="g in groups" :key="g.id" :label="g.name" :value="g.id"/></el-select></el-form-item><el-form-item label="文件"><input data-testid="import-file" type="file" accept=".json,.xlsx,.xls" @change="selected"/></el-form-item></div><el-collapse><el-collapse-item title="字段映射与来源说明（JSON）" name="advanced"><el-form-item label="字段映射：目标字段 → 原始列名"><el-input v-model="mapping" type="textarea" :rows="3"/></el-form-item><el-form-item label="查询与采集说明（sourceDescription、capturedAt 等）"><el-input v-model="context" type="textarea" :rows="3"/></el-form-item></el-collapse-item></el-collapse><p v-if="error" class="error" role="alert">{{error}}</p><el-button type="primary" native-type="submit" :loading="busy" :disabled="!file">预览导入</el-button></el-form></div><div v-if="batch" class="card" data-testid="import-preview"><h2>预览结果 · 批次 {{batch.batchId}}</h2><p class="small">{{batch.status==='COMMITTED'?'已确认写入':'等待核对确认'}} · 文件 SHA-256 {{batch.fileHash}}</p><div class="stats"><div v-for="(label,key) in {sourceRows:'文件实际行数',newRows:'预计新增',updateRows:'预计更新',errorRows:'阻断错误行'}" :key="key" class="stat">{{label}}<strong>{{batch.summary[key]}}</strong></div></div><el-table v-if="batch.errors.length" :data="batch.errors"><el-table-column prop="rowNumber" label="行号" width="80"/><el-table-column prop="fieldName" label="字段" width="130"/><el-table-column prop="code" label="错误码" width="190"/><el-table-column prop="message" label="说明"/></el-table><el-button type="primary" :loading="busy" :disabled="batch.summary.errorRows>0||batch.status==='COMMITTED'" @click="commit">确认写入目录</el-button><span v-if="batch.summary.errorRows>0" class="error"> 请修正文件后重新预览。</span></div></template>
